import React, { useRef, useState } from 'react';

interface RowProps {
  title: string;
  description?: string;
  id: string;
  children: React.ReactNode;
}

const Row: React.FC<RowProps> = ({ title, description, id, children }) => {
  const rowRef = useRef<HTMLDivElement>(null);
  const [isMoved, setIsMoved] = useState(false);

  const handleClick = (direction: 'left' | 'right') => {
    setIsMoved(true);
    if (rowRef.current) {
      const { scrollLeft, clientWidth } = rowRef.current;
      const scrollTo = direction === 'left' 
        ? scrollLeft - clientWidth / 2 
        : scrollLeft + clientWidth / 2;

      rowRef.current.scrollTo({ left: scrollTo, behavior: 'smooth' });
    }
  };

  return (
    <div id={id} className="py-8 pl-4 md:pl-12 relative group z-20">
      <div className="mb-4 pr-12">
        <h2 className="text-2xl md:text-3xl font-bold text-white mb-1 hover:text-gray-300 transition-colors cursor-pointer inline-flex items-center gap-2">
          {title}
          <span className="text-sm font-semibold text-blue-400 opacity-0 group-hover:opacity-100 transition-opacity transform translate-x-[-10px] group-hover:translate-x-0 duration-300">
             See more &gt;
          </span>
        </h2>
        {description && (
          <p className="text-gray-400 text-sm md:text-base max-w-3xl">
            {description}
          </p>
        )}
      </div>

      <div className="relative">
        {/* Left Arrow */}
        <div 
          className={`absolute top-0 bottom-0 left-0 bg-black/50 z-40 w-12 flex items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition duration-200 hover:bg-black/70 ${!isMoved && 'hidden'}`}
          onClick={() => handleClick('left')}
        >
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-8 h-8 text-white">
            <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" />
          </svg>
        </div>

        {/* Scroll Container */}
        <div 
          ref={rowRef}
          className="flex items-stretch space-x-4 overflow-x-scroll no-scrollbar py-4 pr-12"
        >
          {children}
        </div>

        {/* Right Arrow */}
        <div 
          className="absolute top-0 bottom-0 right-0 bg-black/50 z-40 w-12 flex items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition duration-200 hover:bg-black/70"
          onClick={() => handleClick('right')}
        >
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-8 h-8 text-white">
            <path strokeLinecap="round" strokeLinejoin="round" d="M8.25 4.5l7.5 7.5-7.5 7.5" />
          </svg>
        </div>
      </div>
    </div>
  );
};

export default Row;

